import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fs/fsa.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fs/fsa.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fs/fsa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione" tabindex="-1">Introduzione <a class="header-anchor" href="#introduzione" aria-label="Permalink to “Introduzione”">​</a></h1><p>La sezione aurea, inizialmente studiata dai greci (la costruzione che faremo è attribuita ad Erone), fu reintrodotta in Europa durante le crociate, fu poi studiata da Piero Della Francesca (De corporibus regolaris) e divulgata soprattutto ad opera di Luca Pacioli (Divina proporzione, opera a tutti gli ingegni perspicaci curiosa e necessaria) e, nel Rinascimento, fu studiata e cercata in natura soprattutto come rettangolo aureo (rettangolo formato da un segmento e dalla sua sezione aurea).</p><p>Tale rettangolo fu trovato nello sviluppo delle conchiglie, nelle proporzioni del viso e del corpo umano, eccetera...</p><p>Veniva utilizzato quasi universalmente nelle opere di pittura ed architettura.</p><blockquote><p><strong>Nota:</strong> Va detto che la ricerca delle applicazioni della sezione aurea fu condotta anche in modo esagerato: pensate che si cercò di trovare addirittura una corrispondenza fra i tre segmenti della proporzione e la Divina Trinità.</p></blockquote><p>Attualmente l&#39;interesse per questo argomento si è molto ridimensionato, mentre ancora <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>50</mn></mrow><annotation encoding="application/x-tex">50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">50</span></span></span></span> anni fa era uno degli argomenti centrali della geometria.</p><p>Oggi resta ancora importante per gli Istituti d&#39;Arte e per tutte le scuole che si occupino di pittura, scultura ed architettura.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};